on conflict (vendor_id, template_id) do update set
  price = excluded.price,
  is_active = true;

update public.shop_catalog sc
set is_active = false
from public.card_templates t
where sc.template_id = t.id
  and t.category = 'moteur'
  and t.restricted_to_username is null
  and t.code not in ('m_3a', 'm_3c', 'm_16a', 'm_16b', 'm_19a', 'm_19b', 'm_19c', 'm_20b', 'm_20d', 'm_23', 'm_24c', 'm_28b', 'm_28c', 'm_37a', 'm_37b', 'm_38b', 'm_45b', 'm_45c', 'm_47a', 'm_47c', 'm_47d', 'm_49a', 'm_49c', 'm_56a', 'm_56b', 'm_59a', 'm_64c', 'm_67b', 'm_69b', 'm_69c', 'm_71a', 'm_71b', 'm_72a', 'm_72b', 'm_72c', 'm_73b', 'm_73c', 'm_74c', 'm_74d', 'm_86b', 'm_88b', 'm_89c');
